def transform(grid):
    g = np.array(grid)
    out = g.copy()
    cols = sorted(set(np.where(g == 8)[1].tolist()))
    rows = sorted(set(np.where(g == 2)[0].tolist()))
    for x in cols:
        out[:, x] = 8
    emit(out, "Extend each vertical 8 segment into a full column of 8.")
    for y in rows:
        out[y, :] = 2
    emit(out, "Extend each horizontal 2 segment into a full row of 2.")
    for y in rows:
        for x in cols:
            out[y, x] = 4
    emit(out, "Mark each crossing of an 8 column and a 2 row with 4.")
    return out
